<template><div class="app-container content-console"><header><div><h1>{{isActivity?'图文活动管理':'内容管理'}}</h1><p>{{isActivity?'发布图文活动，最新在上；结束的活动自动归入历史，可关联积分转盘。':'修改首页文案、轮播大图与个人页横幅。保存后小程序重新进入页面即可读取。'}}</p></div><el-button :loading="loading" @click="load">刷新</el-button></header><nav><el-button v-if="canRead" @click="router.push('/boost/content')">首页文案与大图</el-button><el-button v-if="canRead" @click="router.push('/boost/activities')">图文活动</el-button><el-button v-if="canRewards" @click="router.push('/boost/rewards')">积分商品与转盘</el-button></nav><el-alert v-if="error" :title="error" type="error" :closable="false" /><template v-if="!isActivity"><el-form v-if="site" label-width="140px" class="site-form" :disabled="!canManage||saving||uploading" v-loading="loading"><h2>页面文字</h2><el-form-item v-for="field in fields" :key="field.key" :label="field.label"><el-input v-model="site[field.key]" :maxlength="field.key==='brand'?12:60" show-word-limit /></el-form-item><h2>首页轮播大图</h2><p>整张图可点击，前端不叠加按钮或文字。支持 1–8 张，按下面顺序显示。</p><div v-for="(banner,i) in site.banners" :key="i" class="banner-editor"><el-form-item :label="'第 '+(i+1)+' 张大图'"><ContentImages :model-value="banner.image?[banner.image]:[]" :limit="1" :disabled="!canManage||saving" @update:model-value="banner.image=$event[0]||''" @busy="setBusy('banner'+i,$event)" /></el-form-item><el-form-item label="图片说明"><el-input v-model="banner.label" maxlength="60" placeholder="仅供无障碍读屏，不叠加在图片上" /></el-form-item><el-form-item label="点击后页面"><el-input v-model="banner.target" placeholder="例如 content/activity?id=1" /><small>market/index、hall/index、content/activities、content/activity?id=活动ID、rewards/mall、rewards/activity?id=转盘ID</small></el-form-item><el-button :disabled="i===0" @click="moveBanner(i,-1)">上移</el-button><el-button :disabled="i===site.banners.length-1" @click="moveBanner(i,1)">下移</el-button><el-button :disabled="site.banners.length===1" @click="site.banners.splice(i,1)">删除此图</el-button></div><el-button :disabled="site.banners.length>=8" @click="site.banners.push({image:'',label:'',target:'content/activities'})">添加轮播图</el-button><h2>个人页大图</h2><el-form-item label="个人页横幅"><ContentImages :model-value="site.profileBannerImage?[site.profileBannerImage]:[]" :limit="1" :disabled="!canManage||saving" @update:model-value="site.profileBannerImage=$event[0]||''" @busy="setBusy('profile',$event)" /><small>上传后整图显示；移除后使用上方配置的个人页横幅文字。</small></el-form-item><el-button v-if="canManage" type="primary" :loading="saving" :disabled="uploading" @click="persistSite">保存页面配置</el-button></el-form></template><template v-else><el-button v-if="canManage" type="primary" class="gap" @click="edit()">发布图文活动</el-button><el-table :data="rows" v-loading="loading"><el-table-column prop="id" label="ID" width="70" /><el-table-column prop="title" label="活动标题" min-width="200" /><el-table-column label="状态"><template #default="s">{{statuses[s.row.status]}} · {{phases[s.row.phase]}}</template></el-table-column><el-table-column prop="publishedAt" label="发布时间" min-width="170" /><el-table-column prop="endsAt" label="结束时间" min-width="170" /><el-table-column label="操作" width="190"><template #default="s"><el-button v-if="canManage" link type="primary" @click="edit(s.row)">编辑 / 上下架</el-button><el-button link @click="copyPath(s.row.id)">复制路径</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load" /></template>
<el-dialog v-model="dialog" title="图文活动" width="760px" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" destroy-on-close><el-form v-if="form" label-width="110px" :disabled="saving"><el-form-item label="标题"><el-input v-model="form.title" maxlength="60" /></el-form-item><el-form-item label="列表摘要"><el-input v-model="form.summary" maxlength="200" /></el-form-item><el-form-item label="封面大图"><ContentImages :model-value="form.cover?[form.cover]:[]" :limit="1" :disabled="saving" @update:model-value="form.cover=$event[0]||''" @busy="setBusy('cover',$event)" /></el-form-item><el-form-item label="活动正文"><el-input v-model="form.body" type="textarea" :rows="5" maxlength="5000" show-word-limit /></el-form-item><el-form-item label="详情图片"><ContentImages v-model="form.detailImages" :disabled="saving" @busy="setBusy('details',$event)" /></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="form.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="form.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-form-item label="关联转盘"><el-input-number v-model="form.rewardActivityId" :min="1" :precision="0" :value-on-clear="null" /><small>选填。在“积分商品与转盘”找到活动 ID；不关联请清空。</small></el-form-item><el-form-item label="发布状态"><el-radio-group v-model="form.status"><el-radio value="DRAFT">草稿</el-radio><el-radio value="PUBLISHED">发布</el-radio><el-radio value="OFFLINE">下架隐藏</el-radio></el-radio-group></el-form-item><p>到期活动保持“发布”即可自动展示在历史活动中；下架会从前端隐藏。</p></el-form><template #footer><el-button :disabled="saving" @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="uploading" @click="persistActivity">保存活动</el-button></template></el-dialog></div></template>
<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import auth from '@/plugins/auth';import {getToken} from '@/utils/auth';import {readSite,saveSite,listActivities,readActivity,saveActivity} from '@/api/content';import ContentImages from './ContentImages.vue'
const route=useRoute(),router=useRouter(),isActivity=computed(()=>route.path.endsWith('/activities')),canRead=computed(()=>auth.hasPermi('boost:content:read')),canManage=computed(()=>auth.hasPermi('boost:content:manage')),canRewards=computed(()=>auth.hasPermi('boost:rewards:read')),loading=ref(false),saving=ref(false),error=ref(''),site=ref(null),rows=ref([]),total=ref(0),page=ref(1),dialog=ref(false),form=ref(null),busyUploads=ref({}),uploading=computed(()=>Object.values(busyUploads.value).some(Boolean));let generation=0,editVersion=0
const fields=[{key:'brand',label:'首页名称'},{key:'tagline',label:'首页简介'},{key:'searchPlaceholder',label:'搜索提示'},{key:'recommendedTitle',label:'推荐标题'},{key:'discoverTitle',label:'发现标题'},{key:'discoverSubtitle',label:'发现说明'},{key:'profileBannerTitle',label:'个人页横幅标题'},{key:'profileBannerSubtitle',label:'个人页横幅说明'}],statuses={DRAFT:'草稿',PUBLISHED:'已发布',OFFLINE:'已下架'},phases={UPCOMING:'未开始',ONGOING:'进行中',ENDED:'已结束'}
function setBusy(key,value){busyUploads.value={...busyUploads.value,[key]:value}}
function moveBanner(i,d){const b=site.value.banners;[b[i],b[i+d]]=[b[i+d],b[i]]}
watch(()=>route.path,()=>{page.value=1;dialog.value=false;editVersion++;load()},{immediate:true});onBeforeUnmount(()=>{generation++;editVersion++})
async function load(){const v=++generation;loading.value=true;error.value='';try{if(!canRead.value)throw Error('当前账号没有内容查看权限');if(isActivity.value){const r=await listActivities({page:page.value});if(v===generation){rows.value=r.data.items;total.value=r.data.total}}else{const r=await readSite();if(v===generation)site.value=r.data}}catch(e){if(v===generation)error.value=e.message||'加载失败'}finally{if(v===generation)loading.value=false}}
async function persistSite(){if(saving.value||uploading.value||!canManage.value)return;saving.value=true;const token=getToken();try{const r=await saveSite(site.value);if(token!==getToken())return;site.value=r.data;ElMessage.success('配置已保存，小程序重新进入页面后生效')}catch(e){error.value=e.message||'保存失败，请刷新核对后重试'}finally{saving.value=false}}
async function edit(row){const v=++editVersion;busyUploads.value={};try{const value=row?(await readActivity(row.id)).data:{title:'',summary:'',cover:'',body:'',detailImages:[],startsAt:'',endsAt:'',status:'DRAFT',rewardActivityId:null,requestKey:crypto.randomUUID()};if(v!==editVersion)return;if(typeof value.detailImages==='string')value.detailImages=JSON.parse(value.detailImages||'[]');form.value=value;dialog.value=true}catch(e){ElMessage.error(e.message||'读取失败')}}
async function persistActivity(){if(saving.value||uploading.value||!canManage.value)return;saving.value=true;const v=editVersion,token=getToken();try{await saveActivity(form.value.id,form.value);if(v!==editVersion||token!==getToken())return;dialog.value=false;ElMessage.success('活动已保存');await load()}catch(e){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}
async function copyPath(id){const text='content/activity?id='+id;try{await navigator.clipboard.writeText(text);ElMessage.success('已复制 '+text)}catch{ElMessage.info(text)}}
</script>
<style scoped>.content-console{max-width:1250px}.content-console header{display:flex;justify-content:space-between;align-items:center}.content-console h1{font-size:26px}.content-console p{color:#667085}.content-console nav{margin:20px 0}.site-form{max-width:850px}.site-form h2{margin:30px 0 18px;font-size:19px}.banner-editor{border:1px solid #e4e7ec;padding:18px;margin:14px 0;border-radius:10px}small{display:block;color:#7c8492;line-height:1.6;width:100%;margin-top:5px}.gap{margin:18px 0}.el-pagination{margin-top:20px}</style>
